            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service {
        public static void execute(Map<Id, SObject> context) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject sObj : context.values()) {
                Contact c = (Contact) sObj;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> accounts = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                accounts = new Map<Id, Account>(
                    [SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                     FROM Account
                     WHERE Id IN :accountIds]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = accounts;
        }
    }
}
